// 
export const proposalSerializedUnsigned = "01000000010000000000a8020000" + payloadSerialized;

export const signature =
	"b34e4815615e9e05ec8402e826c65135efc727bb7b2b2db6b6316ec3c641159bc3a107e71551581c0f90145d1d4458c118ec75e852dd6d13b5de7500356b79f6df56a399184963bf8678162d881b20261473e8f762599f61bcc41bd5e901544c";

export const proposalDataSerializable: Contracts.Crypto.ProposalDataSerializable = {
	...proposalDataSerializableUnsigned,
	signature,
};

export const proposalSerialized = "01000000010000000000a8020000" + payloadSerialized + signature;

export const proposalData: Contracts.Crypto.ProposalData = {
	...proposalDataSerializable,
	blockHeader,
	lockProof: undefined,
};
